selector_to_html = {"a[href=\"intro.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Get Started<a class=\"headerlink\" href=\"#get-started\" title=\"Link to this heading\">#</a></h1><p>For examples of how to apply these actions to new or existing\nprojects, refer to the\n<a class=\"reference external\" href=\"https://github.com/ResearchDataCom/templates\">RDCT Templates Library</a>.</p>", "a[href=\"#authoring\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Authoring<a class=\"headerlink\" href=\"#authoring\" title=\"Link to this heading\">#</a></h2><p>This document is written using\n<a class=\"reference external\" href=\"https://myst-parser.readthedocs.io/\">MyST Markdown</a>, a strict\nsuperset of the\n<a class=\"reference external\" href=\"https://spec.commonmark.org/\">CommonMark syntax specification</a> that\nadds features focused on scientific and technical documentation\nauthoring.  Markdown is specifically designed to be readable across\nmultiple devices in a variety of formats without requiring an online\nInternet connection.  Formatting, collaborative editing, and\npublishing follows the same standards and practices described herein.</p>", "a[href=\"#conventions\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Conventions<a class=\"headerlink\" href=\"#conventions\" title=\"Link to this heading\">#</a></h2><p>Authoritative guidance using these key words appear in admonitions\ntitled \u201cGuidance\u201d, like above.  An explanation of the rationale for\nthe rule plus supporting material appears after in separate\nparagraphs, like this.  Usually, each rule falls under its own\nsubheading, which facilitates cross-referencing.  Top-level headings\nprovide a content summary or a quick reference.</p>", "a[href=\"#scope\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Scope<a class=\"headerlink\" href=\"#scope\" title=\"Link to this heading\">#</a></h2><p>Research Data and Communication Technologies (RDCT) uses this library\nin the development and operation of accredited, validated systems for\ngovernment, for research and education, and for commerce.  This is not\nlimited to pure software engineering and can include, for example,\ndocumentation or system integrations.</p>", "a[href=\"#audience\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Audience<a class=\"headerlink\" href=\"#audience\" title=\"Link to this heading\">#</a></h2><p>As part of RDCT\u2019s commitment to the public benefit, this advances the\nstate of the art by giving the general public ready access to the\nfree/libre/open source technologies and techniques the company uses to\nsecurely lint, test, release, build, publish, deploy, and document a\nvariety of projects.</p>", "a[href=\"roadmap.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Product Roadmap<a class=\"headerlink\" href=\"#product-roadmap\" title=\"Link to this heading\">#</a></h1><p>For the current list of product backlog items, refer to the\n<a class=\"reference external\" href=\"https://github.com/ResearchDataCom/actions/issues?q=is%3Aissue%20state%3Aopen%20type%3AFeature\">issue tracker</a>.</p>", "a[href=\"#structure\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Structure<a class=\"headerlink\" href=\"#structure\" title=\"Link to this heading\">#</a></h2><p>This document contains three major sections.  The frontmatter\nintroduces the project.  The main body of the work explains how to use\nthe composite actions included in this release of the project.\nAppendices organize key reference materials.</p>", "a[href=\"#overview\"]": "<h1 class=\"sd-d-none tippy-header\" style=\"margin-top: 0;\">Overview<a class=\"headerlink\" href=\"#overview\" title=\"Link to this heading\">#</a></h1><h2>Conventions<a class=\"headerlink\" href=\"#conventions\" title=\"Link to this heading\">#</a></h2><p>Authoritative guidance using these key words appear in admonitions\ntitled \u201cGuidance\u201d, like above.  An explanation of the rationale for\nthe rule plus supporting material appears after in separate\nparagraphs, like this.  Usually, each rule falls under its own\nsubheading, which facilitates cross-referencing.  Top-level headings\nprovide a content summary or a quick reference.</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
